const state={page:'login',profile:'Cliente',selectedClient:'Grupo Litoral S.A.',tab:'IVA',openBlocks:{fundamentos:true}};
const clients=[['Grupo Litoral S.A.','30-71452689-1','Servicios','Al día','2'],['Norte Agroindustrial S.A.','30-71245866-4','Agro','Al día','0'],['Delta Servicios S.R.L.','30-71897654-2','Servicios','Atención','3'],['Constructora Paraná S.A.','30-70988732-8','Construcción','Al día','1'],['Inversiones del Nordeste S.A.','30-71543219-7','Finanzas','Al día','0'],['Estancias del Sur S.A.','30-71124578-9','Agro','Crítico','4']];
const nav=[['inicio','Inicio'],['clientes','Clientes'],['documentos','Documentos'],['firmas','Firmas y aprobaciones'],['excepciones','Atención requerida'],['contabilidad','Contabilidad'],['iva','IVA inteligente'],['sueldos','Sueldos'],['conciliacion','Conciliación'],['renta','Renta financiera'],['cierre','Cierre mensual'],['analisis','Análisis Inteligente'],['auditoria','Auditor IA'],['informes','Informes'],['analytics','Analytics'],['metricas','Automatización y ROI'],['vencimientos','Agenda'],['novedades','Novedades'],['emailbot','Email Bot'],['automatizaciones','Automatizaciones'],['trazabilidad','Trazabilidad'],['logs','Logs de acceso'],['colaboradores','Colaboradores'],['usuarios','Roles y permisos'],['administracion','Administración']];
const clientOnly=['inicio','documentos','firmas','contabilidad','informes','analytics','vencimientos','novedades'];
if(location.hash){state.page=location.hash.slice(1).split('?')[0]||'login'}
const stages=[
  ['0','Relevamiento y arquitectura','Comprender la operación y definir una base sólida y segura.','Procesos · Datos · Documentos · Arquitectura · Seguridad',['Reuniones con responsables y relevamiento de procesos actuales.','Inventario de documentos, datos, sistemas y consultas frecuentes.','Modelo inicial de datos, roles, permisos y estrategia documental.'],'Arquitectura aprobada + modelo funcional + plan detallado de implementación.','fundamentos'],
  ['1','Núcleo seguro de la plataforma','Construir los cimientos lógicos, de seguridad y acceso.','Usuarios · Permisos · Seguridad · Datos · Trazabilidad',['Usuarios, organizaciones, colaboradores, roles y sesiones.','Permisos por módulo, cliente y asignaciones; segregación de información.','Backups, logs técnicos y primera capa de trazabilidad.'],'Base empresarial segura para clientes y colaboradores.','fundamentos'],
  ['2','Expediente Digital Inteligente','Centralizar documentos e historia de cada cliente.','Expediente · Documentos · Históricos · Validación · Búsqueda',['Carga individual y múltiple, categorías, períodos, versiones y metadatos.','Procesamiento, extracción, normalización y revisión cuando corresponda.','Buscador, filtros, asociación dato-documento e inicio de migración.'],'Historia digital centralizada, estructurada y trazable por cliente.','core'],
  ['3','Portal y operación interna','Habilitar la primera experiencia real para clientes y estudio.','Dashboard · Clientes · Colaboradores · Vencimientos · Autoservicio',['Portal con documentos, vencimientos, pendientes, novedades e informes habilitados.','Cartera de clientes, responsables, colaboradores y seguimiento interno.','Acceso según permisos y carga de documentación.'],'Primera versión operativa para resolver tareas reales.','core'],
  ['4','Asistente inteligente','Responder consultas a partir del contexto disponible de cada cliente.','IA · Consultas · Documentos · Datos · Fuentes',['Consultas sobre datos estructurados, documentos e información histórica.','Respuestas contextualizadas con fuentes, fecha de actualización y permisos.','Historial, registro de búsquedas y derivación a un colaborador.'],'Resolución automática de una parte de las consultas habituales.','inteligencia'],
  ['5','Comunicación y automatización','Anticiparse a las necesidades mediante reglas y comunicaciones.','Notificaciones · Novedades · Alertas · Reglas · Automatización',['Centro de comunicaciones, novedades, emails, plataforma y push cuando corresponda.','Segmentación, programación, seguimiento de envío y apertura.','Alertas de vencimientos, documentación pendiente y derivaciones.'],'El estudio comienza a trabajar de forma proactiva.','inteligencia'],
  ['6','Inteligencia, informes y proyecciones','Transformar el histórico en conocimiento para decidir mejor.','Analytics · Informes · KPIs · Proyecciones · Oportunidades',['Informes ejecutivos, contables, impositivos, financieros y comparativos.','Indicadores, históricos, filtros, comparaciones y analytics globales.','Escenarios de facturación, gastos, impuestos, liquidez y flujo de fondos.'],'Información útil para clientes y para la gestión estratégica del estudio.','inteligencia'],
  ['7','Producción empresarial','Consolidar la solución para operar a escala.','Mobile · QA · Migración · Performance · Producción',['Experiencia mobile, QA integral, pruebas de permisos y segregación.','Performance, monitoreo, revisión de seguridad y estabilización.','Migración progresiva, capacitación y puesta en producción.'],'Plataforma empresarial consolidada para web y mobile.','produccion']
];
function status(s){let c=s==='Crítico'?'danger':s==='Atención'||s==='Pendiente'?'warn':'';return `<span class="badge ${c}">${s}</span>`}
function app(){document.querySelector('#app').innerHTML=state.page==='login'?login():shell();if(state.page==='etapas')document.querySelector('.transversal')?.insertAdjacentHTML('beforeend',`<article class="card"><h3>Gobernanza de datos</h3><p class="muted">Garantiza origen, calidad, validación, permisos y trazabilidad de la información utilizada por la plataforma y sus procesos de IA.</p></article>`);bind()}
function login(){return `<main class="login"><section class="login-brand"><div class="wordmark">dahlgren<br>y asociados<small>estudio profesional</small></div><div><div class="eyebrow" style="color:#a8cbc6">Plataforma integral</div><h1>La información que impulsa mejores decisiones.</h1><p>Una visión unificada, segura y trazable para la relación entre el estudio y sus clientes.</p></div><small>Prototipo funcional · acceso de demostración</small></section><section class="login-card"><div class="eyebrow">Bienvenido</div><h2>Ingresá a la plataforma</h2><p class="muted">Usá cualquier dato para recorrer la maqueta.</p><label>Email</label><input placeholder="nombre@empresa.com"><label>Contraseña</label><input type="password" placeholder="••••••••"><button class="primary full" data-go="inicio">Ingresar</button><p class="hint">Acceso seguro con perfiles y permisos diferenciados.</p></section></main>`}
function shell(){let menu=(state.profile==='Cliente'?nav.filter(n=>clientOnly.includes(n[0])):nav).map(([id,name])=>`<button data-go="${id}" class="${state.page===id?'active':''}">${name}</button>`).join('');return `<div class="shell"><aside class="sidebar"><div class="wordmark">dahlgren<br>y asociados<small>plataforma integral</small></div><div class="profile"><label>PERFIL DE DEMOSTRACIÓN</label><select id="profile">${['Socio / Administrador','Empleado / Contador','Cliente','Asesor Financiero'].map(x=>`<option ${x===state.profile?'selected':''}>${x}</option>`).join('')}</select></div><nav class="nav">${menu}</nav></aside><main class="main"><header class="topbar"><button class="assist-entry" data-go="comunicaciones"><span>✦</span><b>Mensajes y asistencia</b><small>3 conversaciones activas</small></button><span class="muted top-date">Sábado, 5 de septiembre de 2026</span><input class="search" placeholder="Buscar cliente, documento o dato…"><div class="showcase-menu"><button class="outline showcase-trigger" data-showcase aria-expanded="false">Vista de propuesta <span>⌄</span></button><div class="showcase-dropdown" hidden><div class="showcase-label">Material para presentación</div><button data-go="etapas"><b>Etapas del proyecto</b><small>Ruta de implementación</small></button><button data-go="mobile"><b>Vista mobile</b><small>Experiencia para clientes</small></button></div></div><button class="outline" data-go="notificaciones">◌</button><div class="avatar">DA</div></header><section class="content">${page()}</section></main></div>`}
function header(label,title,text,action=''){return `<div class="page-head"><div><div class="eyebrow">${label}</div><h1>${title}</h1><p>${text}</p></div>${action}</div>`}
function kpi(label,value,detail='',kind=''){return `<article class="card"><div class="kpi-label">${label}</div><div class="kpi-value ${kind}">${value}</div><small class="${kind}">${detail}</small></article>`}
function chart(){let data=[['Oct',12.4],['Nov',13.1],['Dic',11.8],['Ene',14.2],['Feb',15.1],['Mar',16.4],['Abr',15.6],['May',17.3],['Jun',18.1],['Jul',19.6],['Ago',20.4],['Sep',21.8]];let max=Math.max(...data.map(([,value])=>value));return `<div class="chart-title"><div><div class="eyebrow">Facturación mensual</div><p class="muted">Montos netos informados · últimos 12 meses</p></div><div class="chart-total"><b>$21,8 M</b><small>+12,1% vs. agosto</small></div></div><div class="chart">${data.map(([month,value])=>`<div class="chart-column"><span class="bar" style="height:${Math.round(value/max*100)}%" title="${month}: $${value.toLocaleString('es-AR',{minimumFractionDigits:1})} M"><i>$${value.toLocaleString('es-AR',{minimumFractionDigits:1})}M</i></span></div>`).join('')}</div><div class="chart-axis">${data.map(([month])=>`<span>${month}</span>`).join('')}</div><div class="chart-note"><span><i></i> Facturación neta mensual</span><b>Acumulado anual: $196,0 M</b></div>`}
function page(){switch(state.page){case'inicio':return dashboard();case'flujo':return flow();case'etapas':return projectStages();case'mobile':return mobilePreview();case'clientes':return clientsPage();case'documentos':return documents();case'excepciones':return exceptions();case'contabilidad':return accounting();case'asistente':return assistant();case'analisis':return analysisPage();case'informes':return reports();case'analytics':return analytics();case'vencimientos':return deadlines();case'novedades':return news();case'comunicaciones':return communications();case'automatizaciones':return automations();case'trazabilidad':return trace();case'logs':return logs();case'colaboradores':return collaborators();case'usuarios':return users();case'administracion':return admin();case'gobernanza':return governancePage();default:return dashboard()}}
function dashboard(){let client=state.profile==='Cliente';return `${header(client?'Tu empresa':'Visión general',client?'Grupo Litoral S.A.':'Buen día, Rafael',client?'Expediente Digital Inteligente 360°':'Información clave para gestionar el estudio.',client?'':`<button class="primary" data-go="excepciones">Ver atención requerida</button>`)}<div class="grid kpis">${client?[kpi('Situación fiscal','Al día','Sin deudas informadas','positive'),kpi('IVA próximo vencimiento','05/10','Estimado: $8.420.000'),kpi('Documentación pendiente','2','Requiere atención','alert'),kpi('Informes disponibles','5','Último: agosto 2026')]:[kpi('Clientes activos','268','+12 este trimestre','positive'),kpi('Documentos procesados','3.420','Este mes','positive'),kpi('Vencimientos próximos','38','En los próximos 7 días'),kpi('Alertas críticas','6','Requieren atención','alert')]}</div>${client?'':attentionPanel()}<div class="grid two-col"><article class="card"><h3 class="section-title">${client?'Evolución de facturación':'Actividad reciente'}</h3>${client?chart():`<div class="activity"><div><b>Grupo Litoral S.A.</b> consultó IVA 2025 <small>Hace 12 minutos</small></div><div>Se validó declaración de ganancias de <b>Delta S.A.</b> <small>Hace 35 minutos</small></div><div><b>42 clientes</b> recibieron una notificación programada <small>Hoy, 09:00</small></div><div>Se cargó un nuevo balance de <b>Norte Agroindustrial</b> <small>Ayer</small></div></div>`}</article><article class="card"><h3 class="section-title">${client?'Próximos vencimientos':'Automatización'}</h3>${client?`<div class="activity"><div><b>IVA · septiembre 2026</b><br><small>Vence 05/10/2026</small></div><div><b>Anticipo ganancias</b><br><small>Vence 13/10/2026</small></div></div>`:`<div class="kpi-value positive">71%</div><p class="muted">de las consultas fueron resueltas sin intervención humana.</p><button class="outline" data-go="asistente">Ver asistente</button>`}</article></div>${client?`<article class="card access-note"><div><div class="eyebrow">Información habilitada</div><h3 class="section-title">Tu acceso a la información</h3><p class="muted">Podés consultar documentación, obligaciones, informes y datos impositivos habilitados por el estudio. Los indicadores financieros avanzados y la trazabilidad interna no están disponibles para este perfil.</p></div><button class="outline" data-toast="Solicitud de acceso enviada al responsable">Solicitar acceso</button></article>`:''}`}
function flow(){let data=[['01','Ingreso','Documentos, planillas, cargas manuales e integraciones futuras.'],['02','Procesamiento','Extracción, normalización, IA y doble validación.'],['03','Información segura','Datos históricos, relacionados y consultables.'],['04','Expediente 360°','La historia completa de cada cliente en un único lugar.'],['05','Inteligencia','Consultas, informes, reglas y alertas automáticas.'],['06','Comunicación','Avisos y notificaciones personalizadas.'],['07','Analytics','Tendencias, proyecciones y oportunidades.']];return `${header('Recorrido conceptual','Cómo funciona la plataforma','De documentos dispersos a decisiones informadas.') }<div class="grid flow">${data.map(x=>`<article class="card flow-card"><div class="flow-no">${x[0]}</div><h3>${x[1]}</h3><p>${x[2]}</p></article>`).join('')}</div><article class="card" style="margin-top:22px"><b>Expediente Digital Inteligente 360°</b><p class="muted">Toda la historia del cliente en un único lugar, con contexto, permisos y trazabilidad.</p></article>`}
function projectStages(){let block={fundamentos:['A','Fundamentos','Definir correctamente el sistema y construir una base sólida y segura.'],core:['B','Core operativo','Centralizar la información y transformar la operación diaria.'],inteligencia:['C','Inteligencia y automatización','Usar la información acumulada para anticipar y generar conocimiento.'],produccion:['D','Producción empresarial','Consolidar la solución para utilizarla a escala.']};return `${header('Ruta de implementación','Etapas del proyecto','Una implementación progresiva permite validar cada componente y generar valor antes de completar la totalidad de la plataforma.')}<div class="stage-route"><span>Fundamentos</span><i>→</i><span>Core operativo</span><i>→</i><span>Inteligencia y automatización</span><i>→</i><span>Producción empresarial</span></div><div class="stages">${['fundamentos','core','inteligencia','produccion'].map(key=>`<section class="stage-block"><div class="block-head"><span class="block-letter">${block[key][0]}</span><div><div class="eyebrow">Bloque ${block[key][0]}</div><h2>${block[key][1]}</h2><p>${block[key][2]}</p></div></div>${stages.filter(s=>s[6]===key).map(s=>`<article class="card stage-card ${state.openStage===s[0]?'expanded':''}"><div class="stage-summary"><div class="stage-number">${s[0]}</div><div><h3>${s[1]}</h3><p>${s[2]}</p><small>${s[3]}</small></div><button class="outline" data-stage="${s[0]}">${state.openStage===s[0]?'Ocultar detalle':'Ver detalle'}</button></div>${state.openStage===s[0]?`<div class="stage-detail"><div><div class="eyebrow">Incluye</div><ul>${s[4].map(x=>`<li>${x}</li>`).join('')}</ul></div><div class="stage-result"><div class="eyebrow">Resultado de la etapa</div><b>${s[5]}</b></div></div>`:''}</article>`).join('')}</section>`).join('')}</div><section class="project-section"><div class="eyebrow">Presentes durante todo el proyecto</div><h2>Capacidades transversales</h2><div class="grid transversal">${[['Seguridad','Protección, permisos, segregación, auditoría y monitoreo.'],['Trazabilidad','Origen y evolución de datos, documentos, consultas y acciones.'],['QA','Validación funcional continua durante todo el recorrido.'],['UX/UI','Experiencia consistente para clientes y colaboradores.'],['Arquitectura de datos','Diseño preparado para históricos, consultas y crecimiento.'],['Automatización','Identificación continua de procesos repetitivos.']].map(x=>`<article class="card"><h3>${x[0]}</h3><p class="muted">${x[1]}</p></article>`).join('')}</div></section><section class="project-section milestones"><div class="eyebrow">Entregas progresivas</div><h2>No es necesario esperar al final para comenzar a utilizar la plataforma</h2><div class="grid milestone-grid">${[['Hito 1','Base operativa','Usuarios · Clientes · Permisos · Documentos · Expediente · Trazabilidad'],['Hito 2','Autoservicio e inteligencia','Portal · Asistente · Vencimientos · Comunicaciones · Automatizaciones'],['Hito 3','Plataforma empresarial completa','Analytics · Informes · Proyecciones · Mobile · Migración ampliada · Estabilización']].map(x=>`<article class="card"><div class="eyebrow">${x[0]}</div><h3>${x[1]}</h3><p class="muted">${x[2]}</p></article>`).join('')}</div></section><section class="project-close"><div class="eyebrow">Una plataforma que evoluciona junto al estudio</div><h2>Centralizar <span>→</span> Automatizar <span>→</span> Anticipar</h2><p>Cada etapa amplía las capacidades de la anterior, desde la gestión operativa hacia la inteligencia y el análisis estratégico.</p></section>`}
function clientsPage(){return `${header('Estudio','Clientes','Accedé al expediente digital de cada organización.',`<button class="primary" data-modal="client">+ Nuevo cliente</button>`)}<div class="toolbar"><input class="search" placeholder="Buscar por nombre o CUIT"><select><option>Todos los estados</option><option>Con alertas</option></select></div><article class="card table-wrap"><table><thead><tr><th>Cliente</th><th>CUIT</th><th>Actividad</th><th>Estado fiscal</th><th>Pendientes</th><th>Acceso del cliente</th><th></th></tr></thead><tbody>${clients.map(x=>`<tr><td><b>${x[0]}</b></td><td>${x[1]}</td><td>${x[2]}</td><td>${status(x[3])}</td><td>${x[4]}</td><td><button class="outline" data-modal="clientaccess">Configurar</button></td><td><button class="outline" data-client="${x[0]}">Abrir</button></td></tr>`).join('')}</tbody></table></article>`}
function attentionPanel(){let items=[['critical','Delta Servicios S.R.L.','DDJJ de IVA vence en 48 h','Faltan 12 comprobantes para completar el período.','Fiscal'],['warning','Norte Agroindustrial S.A.','Variación salarial atípica','La liquidación preliminar supera 24% el promedio histórico.','Sueldos'],['info','Grupo Litoral S.A.','Conciliación pendiente','Hay 3 movimientos bancarios sin asociar.','Finanzas']];return `<article class="card attention-panel"><div class="attention-head"><div><div class="eyebrow">Trabajo por excepción</div><h3 class="section-title">Atención requerida <span>${items.length}</span></h3><p class="muted">Solo los casos que necesitan criterio profesional o una acción puntual.</p></div><button class="outline" data-go="excepciones">Ver bandeja completa</button></div><div class="attention-list">${items.map(([level,client,title,detail,module])=>`<button class="attention-item" data-go="excepciones"><span class="attention-dot ${level}"></span><span><b>${client}</b><strong>${title}</strong><small>${detail}</small></span><em>${module}</em><i>→</i></button>`).join('')}</div></article>`}
function exceptions(){let items=[['critical','Delta Servicios S.R.L.','DDJJ de IVA vence en 48 h','Faltan 12 comprobantes para completar el período fiscal.','Fiscal','Hoy · 17:00','Solicitar documentación'],['critical','Estancias del Sur S.A.','Factura potencialmente duplicada','Dos comprobantes del mismo proveedor comparten importe, fecha y CAE.','Documentos','Hoy · 14:00','Revisar comprobantes'],['warning','Norte Agroindustrial S.A.','Variación salarial atípica','La liquidación preliminar supera 24% el promedio histórico.','Sueldos','Mañana · 10:00','Ver liquidación'],['warning','Grupo Litoral S.A.','Conciliación bancaria incompleta','Hay 3 movimientos por $1,2 M sin asociar.','Finanzas','08/09 · 12:00','Conciliar ahora'],['info','Constructora Paraná S.A.','Consulta sin resolver','El cliente consulta por una retención; la IA recomienda respuesta validada.','Comunicaciones','08/09 · 16:00','Ver conversación']];return `${header('Control operativo','Atención requerida','Una bandeja única para priorizar excepciones, riesgos y tareas que requieren intervención.',`<button class="primary" data-toast="Vista de prioridades actualizada">Actualizar prioridades</button>`)}<div class="exception-summary"><div><b>5</b><span>casos abiertos</span></div><div><b>2</b><span>críticos</span></div><div><b>18 h</b><span>hasta el próximo vencimiento</span></div><p>La IA prioriza según vencimiento, impacto y contexto del cliente.</p></div><div class="exception-list">${items.map(([level,client,title,detail,module,due,action])=>`<article class="card exception-card"><div class="exception-level ${level}">${level==='critical'?'Crítico':level==='warning'?'Atención':'Seguimiento'}</div><div class="exception-main"><div class="eyebrow">${module} · ${client}</div><h3>${title}</h3><p>${detail}</p><small>Recomendación IA: ${level==='critical'?'priorizar este caso y completar la verificación antes del vencimiento.':'revisar la información asociada y confirmar la acción sugerida.'}</small></div><div class="exception-meta"><span>Fecha límite</span><b>${due}</b><button class="outline" data-toast="Acción preparada: ${action}">${action}</button></div></article>`).join('')}</div>`}
function documents(){let rows=[['DDJJ IVA septiembre 2026','Grupo Litoral S.A.','09/2026','Validado','Datos extraídos · 98% confianza'],['Balance 2025','Norte Agroindustrial S.A.','2025','Requiere revisión','2 observaciones detectadas'],['Extracto Banco Nación','Grupo Litoral S.A.','08/2026','Validado','3 movimientos sugeridos'],['Factura A 0004-003829','Estancias del Sur S.A.','09/2026','Posible duplicado','Coincidencia detectada por IA']];return `${header('Gestión documental','Documentos','Archivos, datos extraídos y procesados en un mismo flujo.',`<div class="header-actions"><button class="outline" data-drive>Carga masiva desde Drive</button><button class="primary" data-modal="document">Subir documento</button></div>`)}<div class="document-insight"><div class="document-insight-icon">✦</div><div><div class="eyebrow">Procesamiento inteligente</div><b>La plataforma identifica, extrae, clasifica y controla cada documento.</b><p>Los casos con baja confianza o inconsistencias pasan automáticamente a Atención requerida.</p></div><div class="document-steps"><span>Tipo y cliente</span><i>→</i><span>Datos extraídos</span><i>→</i><span>Controles IA</span><i>→</i><span>Revisión por excepción</span></div></div><div class="toolbar"><input class="search" placeholder="Buscar documento"><select><option>Todos los clientes</option></select><select><option>Todos los estados</option></select></div><article class="card table-wrap"><table><thead><tr><th>Documento</th><th>Cliente</th><th>Período</th><th>Procesamiento</th><th>Resultado</th><th></th></tr></thead><tbody>${rows.map(([name,client,period,state,result])=>`<tr><td><b>${name}</b></td><td>${client}</td><td>${period}</td><td>${status(state)}</td><td><small class="muted">${result}</small></td><td><button class="outline" data-modal="detail">Ver detalle</button></td></tr>`).join('')}</tbody></table></article>`}
