document.addEventListener('click',e=>{let trigger=e.target.closest('[data-showcase]');if(trigger){let dropdown=trigger.nextElementSibling;let opening=dropdown.hidden;dropdown.hidden=!opening;trigger.setAttribute('aria-expanded',String(opening));return}if(!e.target.closest('.showcase-menu')){let dropdown=document.querySelector('.showcase-dropdown');let trigger=document.querySelector('[data-showcase]');if(dropdown&&!dropdown.hidden){dropdown.hidden=true;trigger?.setAttribute('aria-expanded','false')}}});
function toast(t){let el=document.querySelector('#toast');el.textContent=t;el.style.cssText='position:fixed;right:22px;bottom:22px;background:#123746;color:#fff;padding:13px 17px;border-radius:8px;box-shadow:var(--shadow);z-index:10';setTimeout(()=>el.removeAttribute('style'),2600)}window.addEventListener('hashchange',()=>{let route=location.hash.slice(1).split('?')[0];if(route&&route!==state.page){state.page=route;app()}});app();
modal=function(type){let forms={collaborator:`<label>Nombre y apellido</label><input placeholder="Ej.: Sofía González"><label>Email o usuario</label><input placeholder="sofia@dahlgren.com.ar"><label>Contraseña inicial</label><input type="password" value="Dahlgren2026"><label>Rol</label><select><option>Contador</option><option>Asistente</option><option>Jurídico</option><option>Responsable de área</option></select>`,assignments:`<p class="muted">Seleccioná los clientes sobre los que este colaborador podrá trabajar. Los permisos concretos se definen por rol y área.</p>${clients.map((x,i)=>`<label class="check"><input type="checkbox" ${i<3?'checked':''}> <b>${x[0]}</b> <span class="muted">· ${x[2]}</span></label>`).join('')}`,clientaccess:`<p class="muted">Configurá qué información puede ver la organización en su portal. Estos permisos se aplican sólo a este cliente.</p>${['Documentos habilitados','Situación impositiva','Vencimientos','Informes ejecutivos','Información financiera','Analytics y proyecciones','Actividad y trazabilidad'].map((x,i)=>`<label class="check"><input type="checkbox" ${i<4?'checked':''}> ${x}${i>3?' <span class="muted">(restringido)</span>':''}</label>`).join('')}`,document:`<label>Cliente</label><select><option>Grupo Litoral S.A.</option>${clients.slice(1).map(x=>`<option>${x[0]}</option>`).join('')}</select><label>Documentos</label><input type="file" multiple><p class="muted">Podés seleccionar uno o varios archivos. En esta maqueta se simula la carga de un lote.</p>`,notification:`<label>Título</label><input placeholder="Ej.: Recordatorio de vencimiento"><label>Canales</label><select><option>Push mobile + notificación web</option><option>Push mobile</option><option>Notificación web</option></select><label>Programación</label><select><option>Enviar ahora</option><option>Programar fecha y hora</option><option>Automatizar por condición</option></select>`,email:`<label>Template predefinido</label><select><option>Recordatorio de vencimiento</option><option>Novedad impositiva</option><option>Solicitud de documentación</option><option>Informe disponible</option></select><label>Destinatarios</label><select><option>Clientes seleccionados</option><option>Por actividad</option><option>Con condición específica</option></select><label>Programación</label><select><option>Enviar ahora</option><option>Programar fecha y hora</option><option>Automatizar por condición</option></select>`,news:`<label>Título</label><input placeholder="Título de la novedad"><label>Contenido</label><input placeholder="Resumen para los clientes"><label>Audiencia</label><select><option>Todos los clientes</option><option>Clientes seleccionados</option><option>Por actividad</option></select>`};let content={client:['Nuevo cliente','El alta se simula en esta maqueta.','Crear cliente'],collaborator:['Crear cuenta de colaborador','Definí sus credenciales iniciales y el rol de acceso.','Crear cuenta'],assignments:['Asignaciones de clientes','Mariana López · Contador','Guardar asignaciones'],clientaccess:['Permisos del portal de cliente','Grupo Litoral S.A.','Guardar permisos'],document:['Cargar documentos','Asociá el lote a un cliente y simulá el procesamiento de la carga.','Subir y procesar'],detail:['DDJJ IVA septiembre 2026','<b>IVA determinado:</b> $8.420.000<br><b>Origen:</b> DDJJ IVA septiembre 2026<br><b>Confianza:</b> 98%<br><b>Estado:</b> Validado','Ver origen del dato'],sources:['Fuentes utilizadas','Declaraciones IVA 2025<br>Estado impositivo consolidado<br>Extracto Banco Nación — Agosto 2026','Cerrar'],communication:['Nueva comunicación','Mensaje, audiencia, canales y programación se configurarán en el siguiente paso.','Continuar'],notification:['Crear notificación','Definí cómo y cuándo se avisará a los clientes.','Guardar notificación'],email:['Crear envío de email','Elegí una plantilla y las condiciones de entrega.','Programar email'],news:['Publicar novedad','Compartí información relevante dentro de la plataforma.','Publicar']}[type];document.body.insertAdjacentHTML('beforeend',`<div class="modal" id="modal"><div class="modal-box"><div class="eyebrow">Acción de demostración</div><h2>${content[0]}</h2><p class="muted">${content[1]}</p>${forms[type]||''}<div class="modal-actions"><button class="outline" data-close>Cerrar</button><button class="primary" data-confirm="${type}">${content[2]}</button></div></div></div>`);let layer=document.querySelector('#modal');layer.addEventListener('click',e=>{if(e.target===layer||e.target.closest('[data-close]'))layer.remove();let confirm=e.target.closest('[data-confirm]');if(confirm){if(confirm.dataset.confirm==='document'){let client=layer.querySelector('select').value;confirm.disabled=true;confirm.textContent='Procesando lote…';setTimeout(()=>{layer.querySelector('.modal-box').innerHTML=`<div class="eyebrow">Carga finalizada</div><h2>Documento cargado al cliente</h2><p class="muted">El lote fue procesado y asociado a ${client}. El detalle ya está disponible en Gestión documental.</p><div class="modal-actions"><button class="primary" data-close>Listo</button></div>`},1200)}else{layer.remove();toast('Acción simulada correctamente')}}})};
projectStages=function(){let blocks={fundamentos:{letter:'A',title:'Fundamentos',summary:'Definir con precisión qué se construye, para quién y bajo qué reglas de seguridad.',scope:'Entender la operación real del estudio y convertirla en una arquitectura funcional y segura.',enables:'Evita construir sobre supuestos: deja definidos procesos, datos, permisos y prioridades antes de desarrollar.'},core:{letter:'B',title:'Core operativo',summary:'Transformar la información dispersa en una operación digital centralizada.',scope:'Construir el expediente, los documentos y la primera experiencia real para clientes y colaboradores.',enables:'Permite empezar a operar con clientes reales, con información ordenada, permisos y seguimiento.'},inteligencia:{letter:'C',title:'Inteligencia y automatización',summary:'Usar la información acumulada para responder, anticipar y analizar.',scope:'Incorporar asistencia contextual, comunicaciones proactivas e indicadores que convierten datos en decisiones.',enables:'Reduce tareas repetitivas y abre una relación más proactiva y estratégica con cada cliente.'},produccion:{letter:'D',title:'Producción empresarial',summary:'Preparar la plataforma para una operación estable, segura y escalable.',scope:'Completar pruebas, migración, experiencia mobile y estabilización para el uso cotidiano.',enables:'Consolida una plataforma preparada para escalar la adopción en todo el estudio.'}};return `${header('Ruta de implementación','Etapas del proyecto','Una implementación progresiva permite validar cada componente y generar valor antes de completar la totalidad de la plataforma.')}<div class="stage-route"><span>Fundamentos</span><i>→</i><span>Core operativo</span><i>→</i><span>Inteligencia y automatización</span><i>→</i><span>Producción empresarial</span></div><div class="stages">${Object.entries(blocks).map(([key,b])=>{let isOpen=!!state.openBlocks[key],items=stages.filter(s=>s[6]===key);return `<section class="stage-block ${isOpen?'block-open':''}"><button class="block-head block-toggle" data-block="${key}" aria-expanded="${isOpen}"><span class="block-letter">${b.letter}</span><span class="block-copy"><span class="eyebrow">Bloque ${b.letter}</span><strong>${b.title}</strong><small>${b.summary}</small></span><span class="block-chevron">${isOpen?'−':'+'}</span></button>${isOpen?`<div class="block-content"><div class="block-context"><div><div class="eyebrow">Objetivo del bloque</div><p>${b.scope}</p></div><div><div class="eyebrow">Qué habilita</div><p>${b.enables}</p></div></div><div class="block-stages">${items.map(s=>`<article class="card stage-card ${state.openStage===s[0]?'expanded':''}"><div class="stage-summary"><div class="stage-number">${s[0]}</div><div><h3>${s[1]}</h3><p>${s[2]}</p><small>${s[3]}</small></div><button class="outline" data-stage="${s[0]}">${state.openStage===s[0]?'Ocultar detalle':'Ver alcance'}</button></div>${state.openStage===s[0]?`<div class="stage-detail"><div><div class="eyebrow">Qué se trabaja</div><ul>${s[4].map(x=>`<li>${x}</li>`).join('')}</ul></div><div class="stage-result"><div class="eyebrow">Entregable / resultado</div><b>${s[5]}</b></div></div>`:''}</article>`).join('')}</div></div>`:''}</section>`}).join('')}</div><section class="project-section"><div class="eyebrow">Presentes durante todo el proyecto</div><h2>Capacidades transversales</h2><div class="grid transversal">${[['Seguridad','Protección, permisos, segregación, auditoría y monitoreo.'],['Trazabilidad','Origen y evolución de datos, documentos, consultas y acciones.'],['QA','Validación funcional continua durante todo el recorrido.'],['UX/UI','Experiencia consistente para clientes y colaboradores.'],['Arquitectura de datos','Diseño preparado para históricos, consultas y crecimiento.'],['Automatización','Identificación continua de procesos repetitivos.']].map(x=>`<article class="card"><h3>${x[0]}</h3><p class="muted">${x[1]}</p></article>`).join('')}</div></section><section class="project-section milestones"><div class="eyebrow">Entregas progresivas</div><h2>No es necesario esperar al final para comenzar a utilizar la plataforma</h2><div class="grid milestone-grid">${[['Hito 1','Base operativa','Usuarios · Clientes · Permisos · Documentos · Expediente · Trazabilidad'],['Hito 2','Autoservicio e inteligencia','Portal · Asistente · Vencimientos · Comunicaciones · Automatizaciones'],['Hito 3','Plataforma empresarial completa','Analytics · Informes · Proyecciones · Mobile · Migración ampliada · Estabilización']].map(x=>`<article class="card"><div class="eyebrow">${x[0]}</div><h3>${x[1]}</h3><p class="muted">${x[2]}</p></article>`).join('')}</div></section><section class="project-close"><div class="eyebrow">Una plataforma que evoluciona junto al estudio</div><h2>Centralizar <span>→</span> Automatizar <span>→</span> Anticipar</h2><p>Cada etapa amplía las capacidades de la anterior, desde la gestión operativa hacia la inteligencia y el análisis estratégico.</p></section>`};
function analysisPage(){return `${header('Proactivo y gobernado','Análisis Inteligente','Analiza información confiable del cliente, detecta situaciones y propone acciones.',`<button class="primary" data-run-analysis>Ejecutar análisis</button>`)}<article class="card analysis-intro"><div><div class="eyebrow">Diferencia clave</div><h3>El asistente responde. El análisis detecta y recomienda.</h3><p class="muted">Trabaja únicamente sobre datos, documentos y fuentes autorizadas para el usuario y el cliente analizado.</p></div><div class="governed-flow">Identidad y permisos <span>→</span> Fuentes autorizadas <span>→</span> Datos confiables <span>→</span> Análisis <span>→</span> Recomendación trazable</div></article><div class="grid kpis">${kpi('Clientes analizados','86','En los últimos 30 días','positive')}${kpi('Hallazgos importantes','14','Requieren revisión','alert')}${kpi('Recomendaciones pendientes','22','Con revisión humana')}${kpi('Informes para actualizar','9','Por nueva información')}</div><article class="card table-wrap" style="margin-top:18px"><h3 class="section-title">Análisis recientes</h3><table><thead><tr><th>Cliente</th><th>Último análisis</th><th>Hallazgos</th><th>Prioridad</th><th>Responsable</th><th></th></tr></thead><tbody><tr><td><b>Grupo Litoral S.A.</b></td><td>05/09/2026 · 18:42</td><td>3</td><td>${status('Importante')}</td><td>Mariana López</td><td><button class="outline" data-run-analysis>Ver análisis</button></td></tr><tr><td><b>Delta Servicios S.R.L.</b></td><td>05/09/2026 · 16:10</td><td>2</td><td>${status('Atención')}</td><td>Lucas Martínez</td><td><button class="outline" data-run-analysis>Ver análisis</button></td></tr></tbody></table></article>`}
function governancePage(){return `${header('Administración','Gobierno del dato','Origen, calidad, responsabilidad y trazabilidad para información confiable.')}<div class="grid kpis">${kpi('Datos validados','12.486','Actualizados y aprobados','positive')}${kpi('Pendientes de revisión','37','Requieren responsable','alert')}${kpi('Inconsistencias','8','Entre fuentes')}${kpi('Documentos sin procesar','14','En cola')}</div><div class="grid two-col"><article class="card"><h3 class="section-title">Calidad demostrativa de la información</h3><div class="quality"><div>Fiscal <b>96%</b><span style="width:96%"></span></div><div>Contable <b>94%</b><span style="width:94%"></span></div><div>Financiera <b>88%</b><span style="width:88%"></span></div><div>Jurídica <b>91%</b><span style="width:91%"></span></div><div>Laboral <b>85%</b><span style="width:85%"></span></div></div><p class="muted">Indicadores demostrativos de completitud y validación; no representan un scoring real.</p></article><article class="card"><h3 class="section-title">Políticas de gobierno</h3><div class="policy-list">${['Datos críticos','Fuentes autorizadas','Validación profesional','Retención e historial','Acceso por permisos','Uso responsable por IA'].map(x=>`<span>${x}</span>`).join('')}</div><p class="muted">Las políticas se presentan conceptualmente en esta maqueta.</p></article></div><article class="card table-wrap" style="margin-top:18px"><h3 class="section-title">Pendientes de revisión</h3><table><thead><tr><th>Cliente</th><th>Dato / documento</th><th>Área</th><th>Motivo</th><th>Fecha</th><th>Responsable</th><th></th></tr></thead><tbody><tr><td>Grupo Litoral S.A.</td><td>Extracto Banco Nación</td><td>Financiera</td><td>Diferencia entre fuentes</td><td>05/09/2026</td><td>Mariana López</td><td><button class="outline" data-modal="detail">Revisar</button></td></tr><tr><td>Delta Servicios S.R.L.</td><td>DDJJ IIBB agosto</td><td>Fiscal</td><td>Requiere validación profesional</td><td>04/09/2026</td><td>Lucas Martínez</td><td><button class="outline" data-modal="detail">Revisar</button></td></tr></tbody></table></article>`}
function runAnalysis(){document.body.insertAdjacentHTML('beforeend',`<div class="modal" id="analysis-modal"><div class="modal-box analysis-modal"><div class="eyebrow">Análisis Inteligente · Grupo Litoral S.A.</div><h2>Revisando información autorizada</h2><div class="analysis-steps">${['Datos contables e impositivos','Documentación validada','Históricos disponibles','Vencimientos y situación financiera','Consultas, informes, alertas y novedades'].map(x=>`<div>◌ ${x}</div>`).join('')}</div><div class="modal-actions"><button class="outline" data-analysis-close>Cancelar</button></div></div></div>`);let layer=document.querySelector('#analysis-modal');layer.addEventListener('click',e=>{if(e.target===layer||e.target.closest('[data-analysis-close]'))layer.remove()});setTimeout(()=>{if(!document.querySelector('#analysis-modal'))return;layer.querySelector('.analysis-modal').innerHTML=`<div class="eyebrow">Análisis completado</div><h2>3 situaciones requieren atención</h2><p class="muted">05/09/2026 · 18:42 · 1.284 datos · 437 documentos · histórico de 36 meses</p><div class="analysis-results"><div><b>IVA +27%</b><small>Respecto del promedio de seis meses.</small><button class="outline" data-toast="Fuentes: DDJJ IVA y histórico fiscal">Ver fuentes</button></div><div><b>Faltan 2 comprobantes</b><small>Recomendación: solicitar documentación pendiente.</small><button class="outline" data-toast="Notificación sugerida creada">Crear notificación</button></div><div><b>Informe ejecutivo</b><small>Requiere actualización por nueva información fiscal.</small><button class="outline" data-toast="Regeneración de informe simulada">Regenerar</button></div></div><div class="modal-actions"><button class="outline" data-toast="Recomendaciones marcadas como revisadas" data-analysis-close>Marcar revisado</button><button class="primary" data-analysis-close>Ver historial</button></div>`},1300)}
document.addEventListener('click',e=>{if(e.target.closest('[data-run-analysis]'))runAnalysis()});
document.addEventListener('click',e=>{let action=e.target.closest('#analysis-modal [data-toast]');if(action)toast(action.dataset.toast)});
app();
function mobilePreview(){let phone=(title,content)=>`<article class="phone"><div class="phone-speaker"></div><div class="phone-screen"><div class="mobile-top"><span>9:41</span><span>● ◔ ▰</span></div><div class="mobile-brand">dahlgren <small>y asociados</small></div>${content}<div class="mobile-nav"><span>⌂<small>Inicio</small></span><span>▣<small>Documentos</small></span><span>◌<small>Alertas</small></span><span>☻<small>Perfil</small></span></div></div><p>${title}</p></article>`;return `${header('Presentación de experiencia','Vista mobile','Una primera visión de los flujos principales en dispositivos móviles.')}<div class="mobile-intro"><span class="badge">Prototipo visual</span><p>Las pantallas se presentan como referencias de validación; el flujo completo se definirá en etapas posteriores.</p></div><div class="phone-gallery">${phone('Inicio del cliente',`<div class="mobile-content"><div class="mobile-hello">Hola, Grupo Litoral <span>⌄</span></div><div class="mobile-hero"><small>Situación fiscal</small><b>Al día</b><span>✓</span><p>Tu información está actualizada.</p></div><div class="mobile-mini-grid"><div><small>Próximo vencimiento</small><b>05 OCT</b></div><div><small>Documentos</small><b>2 pendientes</b></div></div><h4>Acciones rápidas</h4><div class="mobile-actions"><button>◌ Preguntar al asistente</button><button>↑ Subir documentos</button><button>▣ Ver vencimientos</button></div></div>`)}${phone('Asistente inteligente',`<div class="mobile-content"><div class="mobile-hello">Asistente inteligente</div><p class="mobile-sub">Información disponible de Grupo Litoral S.A.</p><div class="mobile-user-msg">¿Cuándo vence mi próxima obligación?</div><div class="mobile-bot-msg"><b>IVA septiembre 2026</b><br>Vence el 05/10/2026. El importe estimado es de $8.420.000.<small>Fuentes: DDJJ IVA · Vencimientos</small></div><div class="mobile-chip-row"><span>Documentación pendiente</span><span>Último informe</span></div><div class="mobile-input">Escribí tu consulta <b>↑</b></div></div>`)}${phone('Documentos y carga',`<div class="mobile-content"><div class="mobile-hello">Documentos <button class="mobile-plus">+</button></div><div class="mobile-filter">Todos los documentos ·⌄</div><div class="mobile-document"><span>PDF</span><div><b>DDJJ IVA septiembre</b><small>Actualizado hoy · Validado</small></div><i>›</i></div><div class="mobile-document"><span>XLS</span><div><b>Extracto Banco Nación</b><small>Agosto 2026 · Validado</small></div><i>›</i></div><div class="mobile-document"><span>PDF</span><div><b>Balance 2025</b><small>Requiere revisión</small></div><i>›</i></div><button class="mobile-upload">↑ Subir documentación</button></div>`)}${phone('Novedades y alertas',`<div class="mobile-content"><div class="mobile-hello">Novedades</div><div class="mobile-notice"><span class="badge warn">Atención</span><h4>Próximo vencimiento de IVA</h4><p>Recordá realizar el pago antes del día 5 para mantener el beneficio correspondiente.</p><small>Hace 2 horas</small></div><div class="mobile-notice"><span class="badge">Información</span><h4>Informe ejecutivo disponible</h4><p>Ya podés consultar el resumen mensual de agosto 2026.</p><small>Hace 1 día</small></div><button class="mobile-upload">Ver todas las novedades</button></div>`)} </div><p class="muted" style="margin-top:18px">Deslizá horizontalmente para recorrer las pantallas.</p>`}
function automations(){let rules=[['IVA próximo a vencer','5 días antes','Notificar cliente','Fiscal'],['Documentación pendiente','48 h sin recibir','Enviar recordatorio','Documental'],['Nuevo documento','Al incorporarse','Procesar · Actualizar expediente · Ejecutar análisis','Operativa'],['Alerta crítica detectada','Al detectarse','Notificar responsable','Alertas']];return `${header('Operación proactiva','Automatizaciones','El sistema no solamente almacena información: trabaja con ella.',`<button class="primary" data-toast="Nueva regla de automatización simulada">+ Nueva automatización</button>`)}<div class="automation-list">${rules.map((r,i)=>`<article class="card automation-card"><div class="automation-icon">${['◷','▣','↑','!'][i]}</div><div class="automation-rule"><div class="eyebrow">${r[3]}</div><h3>${r[0]}</h3><p><b>Cuando:</b> ${r[1]} <span>→</span> <b>Entonces:</b> ${r[2]}</p></div><div class="automation-state"><span class="badge">ACTIVA</span><button class="toggle on" aria-label="Automatización activa"></button></div></article>`).join('')}</div><article class="card automation-footer"><div><div class="eyebrow">Control humano</div><h3>Las reglas automatizan avisos y tareas repetitivas.</h3><p class="muted">Las acciones sensibles, como aprobar datos o ejecutar decisiones relevantes, continúan requiriendo validación profesional.</p></div><button class="outline" data-go="analisis">Ver Análisis Inteligente</button></article>`}
function openDriveLoad(){document.body.insertAdjacentHTML('beforeend',`<div class="modal" id="drive-modal"><div class="modal-box"><div class="eyebrow">Carga masiva · demostración</div><h2>Importar documentos desde Drive</h2><p class="muted">Seleccioná una carpeta para asociar su contenido al cliente. No se conecta a Google Drive en esta maqueta.</p><label>Cliente</label><select><option>Grupo Litoral S.A.</option><option>Norte Agroindustrial S.A.</option><option>Delta Servicios S.R.L.</option></select><label>Carpeta de origen</label><div class="drive-folder">▣ Drive / Grupo Litoral / Septiembre 2026</div><div class="modal-actions"><button class="outline" data-drive-close>Cancelar</button><button class="primary" data-drive-import>Importar lote</button></div></div></div>`);let layer=document.querySelector('#drive-modal');layer.addEventListener('click',e=>{if(e.target===layer||e.target.closest('[data-drive-close]'))layer.remove();if(e.target.closest('[data-drive-import]')){e.target.closest('[data-drive-import]').textContent='Importando y procesando…';setTimeout(()=>{layer.querySelector('.modal-box').innerHTML=`<div class="eyebrow">Carga finalizada</div><h2>12 documentos incorporados</h2><p class="muted">El lote fue asociado a Grupo Litoral S.A. y quedó disponible para procesamiento y validación.</p><div class="modal-actions"><button class="primary" data-drive-close>Listo</button></div>`},1000)}})}
