function areasHub(){let cards=Object.entries(areaCatalog).map(([id,a])=>`<button class="area-card ${a.tone}" data-go="areas/${id}"><span class="area-icon">${a.icon}</span><span class="area-card-top"><b>${a.name}</b><small>${a.lead}</small></span><span class="area-card-copy">${a.description}</span><span class="area-card-stats"><i>${a.clients}</i><i>${a.pending}</i><i class="${a.alerts.includes('crít')?'critical':''}">${a.alerts}</i></span><span class="area-card-link">Abrir workspace <em>→</em></span></button>`).join('');return `${header('Estructura operativa','Áreas','Una plataforma integrada con espacios de trabajo especializados para cada equipo.')}<section class="areas-intro"><div><div class="eyebrow">Una plataforma. Equipos especializados.</div><h2>Cada área tiene foco propio, sin perder el contexto del estudio.</h2><p>Clientes, documentos, agenda, automatizaciones, seguridad e inteligencia artificial permanecen conectados como servicios transversales.</p></div><button class="outline" data-go="excepciones">Ver atención transversal</button></section><div class="area-grid">${cards}</div><section class="shared-services"><div><div class="eyebrow">Servicios compartidos</div><h3>Conectados en toda la plataforma</h3></div><div><span>Clientes</span><span>Documentos</span><span>Agenda</span><span>Automatizaciones</span><span>IA</span><span>Seguridad</span><span>Trazabilidad</span></div></section>`}
function areaWorkspace(areaId,tab='resumen'){let a=areaCatalog[areaId]||areaCatalog.fiscal;let tabName=(a.tabs.find(x=>x[0]===tab)||a.tabs[0])[1];let highlights={fiscal:['DDJJ próximas','4','IVA en preparación','18','Clientes completos','118'],laboral:['Liquidaciones pendientes','3','Novedades recibidas','24','LSD por preparar','2'],contabilidad:['Cierres en curso','12','Asientos sugeridos','46','Saldos a revisar','3'],auditoria:['Controles ejecutados','1.248','Hallazgos activos','4','Riesgos altos','2'],finanzas:['Movimientos sin asociar','3','Conciliación estimada','87%','Proyecciones activas','8'],documental:['Documentos recibidos hoy','48','Procesados automáticamente','41','Requieren revisión','3'],atencion:['Conversaciones activas','9','Resueltas por IA','68%','Casos escalados','2']}[areaId]||[];return `${header('Áreas / '+a.name,a.name,a.description,`<button class="primary" data-toast="Agente ${a.name} abierto en modo demostración">Consultar agente IA</button>`)}<section class="workspace-hero ${a.tone}"><div><span class="area-icon">${a.icon}</span><div><div class="eyebrow">Workspace de área</div><h2>${a.name}</h2><p>Responsable: <b>${a.lead}</b> · ${a.clients}</p></div></div><div class="workspace-state"><b>${a.pending}</b><small>${a.alerts}</small></div></section><nav class="area-tabs">${a.tabs.map(([id,label])=>`<button class="${id===tab?'active':''}" data-go="areas/${areaId}/${id}">${label}</button>`).join('')}</nav><div class="workspace-context"><span>Área</span><b>${a.name}</b><i>›</i><span>Módulo</span><b>${tabName}</b><small>Información demo · permisos según rol y cliente</small></div><div class="grid kpis">${[0,3,6].map(i=>kpi(highlights[i],highlights[i+1],i===6?'Requiere seguimiento':'Actualizado hoy',i===6?'alert':'positive')).join('')}</div><section class="workspace-body"><article class="card"><div class="eyebrow">${tabName}</div><h3>${tab==='resumen'?'Trabajo priorizado del área':'Vista de '+tabName}</h3><p class="muted">Este espacio concentra las tareas, controles, alertas y clientes relacionados con ${a.name.toLowerCase()}. La navegación contextual mantiene el menú principal simple.</p><div class="workspace-list"><span><b>Cliente relacionado</b> Grupo Litoral S.A.<small>Actualizado hace 12 min</small></span><span><b>Control pendiente</b> Revisión profesional requerida<small>Prioridad alta</small></span><span><b>Automatización</b> Regla ejecutada correctamente<small>Con trazabilidad disponible</small></span></div></article><article class="card workspace-agent"><div class="eyebrow">Agente especializado</div><h3>Agente ${a.name}</h3><p>Analiza únicamente información autorizada de su dominio, propone acciones y deja cada resultado trazado.</p><button class="outline" data-toast="Consulta preparada para el agente ${a.name}">Hacer una consulta</button></article></section><button class="back-to-areas" data-go="areas">← Volver al Hub de Áreas</button>`}
const originalPage=page;
page=function(){if(state.page==='areas')return areasHub();if(state.page.startsWith('areas/')){let parts=state.page.split('/');return areaWorkspace(parts[1],parts[2]||'resumen')}switch(state.page){case'firmas':return signatures();case'iva':return ivaSmart();case'sueldos':return payroll();case'conciliacion':return reconciliation();case'renta':return investmentIncome();case'cierre':return monthlyClose();case'auditoria':return aiAudit();case'metricas':return automationMetrics();case'emailbot':return emailBot();case'cliente360':return client360();default:return originalPage()}};
shell=function(){let clientMenu=[['inicio','Inicio'],['documentos','Documentos'],['firmas','Firmas'],['contabilidad','Contabilidad'],['informes','Informes'],['analytics','Analytics'],['vencimientos','Agenda'],['novedades','Novedades'],['comunicaciones','Mensajes y asistencia']];let item=([id,label])=>`<button data-go="${id}" class="${state.page===id?'active':''}">${label}</button>`;let group=(title,items,open=false)=>`<section class="side-group ${open?'open':''}"><button class="side-group-toggle" data-nav-group><span>${title}</span><i>⌄</i></button><div class="side-group-items">${items.map(item).join('')}</div></section>`;let agents=Object.entries(areaCatalog).map(([id,a])=>`<button class="agent-nav ${a.tone} ${state.page.startsWith('areas/'+id)?'active':''}" data-go="areas/${id}"><span class="agent-nav-icon">${a.icon}</span><span><b>Agente ${a.name}</b><small>${a.pending}</small></span><i>${a.alerts.split(' ')[0]}</i></button>`).join('');let navigation=state.profile==='Cliente'?`<nav class="nav client-nav">${clientMenu.map(item).join('')}</nav>`:`<nav class="nav grouped-nav"><section class="side-primary">${[['inicio','Inicio'],['clientes','Clientes'],['excepciones','Atención requerida']].map(item).join('')}</section><section class="agents-group"><div class="side-label">Agentes del estudio</div>${agents}</section>${group('Operación',[['documentos','Documentos'],['vencimientos','Agenda'],['automatizaciones','Automatizaciones'],['comunicaciones','Comunicaciones'],['analisis','Asistente del estudio']],true)}${group('Dirección',[['informes','Informes y Analytics'],['metricas','Automatización y ROI']],state.profile==='Socio / Administrador')}${group('Gobierno y seguridad',[['trazabilidad','Trazabilidad'],['logs','Logs de acceso'],['colaboradores','Colaboradores'],['usuarios','Roles y permisos'],['administracion','Administración']])}</nav>`;return `<div class="shell"><aside class="sidebar"><div class="wordmark">dahlgren<br>y asociados<small>plataforma integral</small></div><div class="profile"><label>PERFIL DE DEMOSTRACIÓN</label><select id="profile">${['Socio / Administrador','Empleado / Contador','Cliente','Asesor Financiero'].map(x=>`<option ${x===state.profile?'selected':''}>${x}</option>`).join('')}</select></div>${navigation}</aside><main class="main"><header class="topbar"><button class="assist-entry" data-go="comunicaciones"><span>✦</span><b>Mensajes y asistencia</b><small>3 conversaciones activas</small></button><span class="muted top-date">Martes, 8 de septiembre de 2026</span><input class="search" placeholder="Buscar cliente, documento o dato…"><div class="showcase-menu"><button class="outline showcase-trigger" data-showcase aria-expanded="false">Vista de propuesta <span>⌄</span></button><div class="showcase-dropdown" hidden><div class="showcase-label">Material para presentación</div><button data-go="areas"><b>Mapa de áreas</b><small>Visión integral de los equipos</small></button><button data-go="etapas"><b>Etapas del proyecto</b><small>Ruta de implementación</small></button><button data-go="mobile"><b>Vista mobile</b><small>Experiencia para clientes</small></button></div></div><button class="outline" data-go="inicio">◌</button><div class="avatar">DA</div></header><section class="content">${page()}</section></main></div>`};
